// NOTE: Since we don't have large files in this sandbox, we will
// simulate a Readable Stream using Node's built-in array stream.
const { Readable } = require('stream');

// Creating a custom Readable stream from an array
const myStream = Readable.from(['Chunk 1 ', 'Chunk 2 ', 'Chunk 3']);

console.log("Starting stream...");

// Listen for data chunks
myStream.on('data', (chunk) => {
  console.log(`Received: ${chunk}`);
});

// Listen for the end of the file
myStream.on('end', () => {
  console.log("Stream finished successfully!");
});

// If there's an error (e.g. file missing), handle it!
myStream.on('error', (err) => {
  console.error("Stream crashed!", err);
});
